            case "MENOS50" -> new BigDecimal("50.00");
            case "FRETEGRATIS" -> BigDecimal.ZERO;
            case "LEVE3PAGUE2" -> calcularDescontoLeve3Pague2(itens);
            default -> BigDecimal.ZERO;
        };
